# Independent explicit source-field oracle, not generated by JavaScript implementation.
import json
from pathlib import Path
def u(v,n): return list(v.to_bytes(n,'big'))
# Type02, reserved7, layer1, x80 y0 w16 h16, mode1 speed240 stay0,
# payload length512; each opaque red RGB444 pixel is 0f00, column-major.
body=[2]+[0]*7+[1]+u(80,2)+u(0,2)+u(16,2)+u(16,2)+[1,240,0]+u(512,4)+[15,0]*256
Path(__file__).with_name('square-vector.json').write_text(json.dumps({'graffitiRedAt80':u(len(body)+4,4)+body})+'\n')
